35	import org.springframework.samples.petclinic.model.Owner;
36	import org.springframework.samples.petclinic.model.Pet;
37	import org.springframework.samples.petclinic.model.Visit;
38	import org.springframework.samples.petclinic.rest.advice.DuplicateHouseholdException;
39	import org.springframework.samples.petclinic.rest.advice.DuplicateTelephoneException;
40	import org.springframework.samples.petclinic.rest.advice.InvalidFieldValueException;
41	import org.springframework.samples.petclinic.rest.advice.MissingRequiredFieldsException;
42	import org.springframework.samples.petclinic.rest.api.OwnersApi;
43	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
44	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
45	import org.springframework.samples.petclinic.rest.dto.PetDto;
46	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
47	import org.springframework.samples.petclinic.rest.dto.VisitDto;
48	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
49	import org.springframework.samples.petclinic.service.ClinicService;
50	import org.springframework.security.access.prepost.PreAuthorize;
51	import org.springframework.web.bind.annotation.CrossOrigin;
52	import org.springframework.web.bind.annotation.RequestMapping;
53	import org.springframework.web.bind.annotation.RestController;
54	import org.springframework.web.util.UriComponentsBuilder;
55	
56	import jakarta.transaction.Transactional;
57	
58	/**
59	 * @author Vitaliy Fedoriv
60	 */
61	
62	@RestController
63	@CrossOrigin(exposedHeaders = "errors, content-type")
64	@RequestMapping("/api")
65	public class OwnerRestControllerV1 implements OwnersApi {
66	
67	    /**
68	     * Basic syntactic email check: a non-empty local part, an '@', and a domain containing at least
69	     * one dot, with no whitespace anywhere. Deliberately permissive but requires the essential shape.
70	     */
71	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
72	
73	    private final ClinicService clinicService;
74	
75	    private final OwnerMapper ownerMapper;
76	
77	    private final PetMapper petMapper;
78	
79	    private final VisitMapper visitMapper;
80	
81	    public OwnerRestControllerV1(ClinicService clinicService,
82	                                 OwnerMapper ownerMapper,
83	                                 PetMapper petMapper,
84	                                 VisitMapper visitMapper) {
85	        this.clinicService = clinicService;
86	        this.ownerMapper = ownerMapper;
87	        this.petMapper = petMapper;
88	        this.visitMapper = visitMapper;
89	    }
90	
91	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
92	    @Override
93	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
94	        Collection<Owner> owners;
95	        if (lastName != null) {
96	            owners = this.clinicService.findOwnerByLastName(lastName);
97	        } else {
98	            owners = this.clinicService.findAllOwners();
99	        }
100	        if (owners.isEmpty()) {
101	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
102	        }
103	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
104	    }
105	
106	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
107	    @Override
108	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
109	        Owner owner = this.clinicService.findOwnerById(ownerId);
110	        if (owner == null) {
111	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
112	        }
113	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
114	    }
115	
116	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
117	    @Override
118	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
119	        List<String> missingFields = new ArrayList<>();
120	        requireNonBlank(missingFields, "firstName", ownerFieldsDto.getFirstName());
121	        requireNonBlank(missingFields, "lastName", ownerFieldsDto.getLastName());
122	        String normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
123	        requireNonBlank(missingFields, "address", normalizedAddress);
124	        requireNonBlank(missingFields, "city", ownerFieldsDto.getCity());
125	        requireNonBlank(missingFields, "telephone", ownerFieldsDto.getTelephone());
126	        if (!missingFields.isEmpty()) {
127	            throw new MissingRequiredFieldsException(missingFields);
128	        }
129	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
130	        requireUniqueTelephone(normalizedTelephone);
131	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
132	        if (!sharesHousehold) {
133	            requireUniqueHousehold(ownerFieldsDto.getLastName(), normalizedAddress);
134	        }
135	        ownerFieldsDto.setTelephone(normalizedTelephone);
136	        if (ownerFieldsDto.getEmail() != null) {
137	            ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
138	        }
139	        HttpHeaders headers = new HttpHeaders();
140	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
141	        owner.setAddress(normalizedAddress);
142	        if (owner.getRegistrationDate() == null) {
143	            owner.setRegistrationDate(LocalDate.now());
144	        }
145	        owner.setCustomerCode(nextCustomerCode(owner.getLastName()));
146	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
147	        if (sharesHousehold) {
148	            owner.setHouseholdId(joinHousehold(owner.getLastName(), owner.getAddress()));
149	        }
150	        this.clinicService.saveOwner(owner);
151	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
152	        headers.setLocation(UriComponentsBuilder.newInstance()
153	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
154	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
155	    }
156	
157	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
158	    @Override
159	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
160	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
161	        if (currentOwner == null) {
162	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
163	        }
164	        currentOwner.setAddress(ownerFieldsDto.getAddress());
165	        currentOwner.setCity(ownerFieldsDto.getCity());
166	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
167	        currentOwner.setLastName(ownerFieldsDto.getLastName());
168	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
169	        this.clinicService.saveOwner(currentOwner);
170	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
171	    }
172	
173	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
174	    @Transactional
175	    @Override
176	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
177	        Owner owner = this.clinicService.findOwnerById(ownerId);
178	        if (owner == null) {
179	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
180	        }
181	        this.clinicService.deleteOwner(owner);
182	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
183	    }
184	
185	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
186	    @Override
187	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
188	        Owner owner = this.clinicService.findOwnerById(ownerId);
189	        if (owner == null) {
190	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
191	        }
192	        HttpHeaders headers = new HttpHeaders();
193	        Pet pet = petMapper.toPet(petFieldsDto);
194	        owner.setId(ownerId);
195	        pet.setOwner(owner);
196	        pet.getType().setName(null);
197	        this.clinicService.savePet(pet);
198	        PetDto petDto = petMapper.toPetDto(pet);
199	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
200	            .buildAndExpand(pet.getId()).toUri());
201	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
202	    }
203	
204	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
205	    @Override
206	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
207	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
208	        if (currentOwner != null) {
209	            Pet currentPet = this.clinicService.findPetById(petId);
210	            if (currentPet != null) {
211	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
212	                currentPet.setName(petFieldsDto.getName());
213	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
214	                this.clinicService.savePet(currentPet);
215	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
216	            }
217	        }
218	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
219	    }
220	
221	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
222	    @Override
223	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
224	        HttpHeaders headers = new HttpHeaders();
225	        Visit visit = visitMapper.toVisit(visitFieldsDto);
226	        Pet pet = new Pet();
227	        pet.setId(petId);
228	        visit.setPet(pet);
229	        this.clinicService.saveVisit(visit);
230	        VisitDto visitDto = visitMapper.toVisitDto(visit);
231	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
232	            .buildAndExpand(visit.getId()).toUri());
233	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
234	    }
235	
236	
237	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
238	    @Override
239	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
240	        Owner owner = this.clinicService.findOwnerById(ownerId);
241	        if (owner != null) {
242	            Pet pet = owner.getPet(petId);
243	            if (pet != null) {
244	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
245	            }
246	        }
247	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
248	    }
249	
250	    /**
251	     * Builds the owner's customer code as {@code '<LAST3>-<NNNN>'}, where {@code LAST3} is the
252	     * upper-cased first three letters of {@code lastName} and {@code NNNN} is a global 4-digit
253	     * zero-padded sequence equal to one more than the current number of owners (e.g. {@code SMI-0007}).
254	     *
255	     * @param lastName the owner's last name (already validated non-blank)
256	     * @return the formatted customer code for the owner being created
257	     */
258	    private String nextCustomerCode(String lastName) {
259	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
260	        int sequence = this.clinicService.findAllOwners().size() + 1;
261	        return String.format("%s-%04d", last3, sequence);
262	    }
263	
264	    /**
265	     * Counts the existing owners (those already persisted before this create) whose first and last
266	     * names both match the incoming owner's, compared case-insensitively. This snapshot is stored on
267	     * the new owner as its {@code namesakeCount} and echoed back on reads.
268	     *
269	     * @param firstName the incoming owner's first name (already validated non-blank)
270	     * @param lastName the incoming owner's last name (already validated non-blank)
271	     * @return the number of existing namesakes sharing both names case-insensitively
272	     */
273	    private int countNamesakes(String firstName, String lastName) {
274	        return (int) this.clinicService.findAllOwners().stream()
275	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
276	                && lastName.equalsIgnoreCase(existing.getLastName()))
277	            .count();
278	    }
279	
280	    /**
281	     * Records {@code fieldName} as missing when {@code value} is {@code null} or blank (empty or
282	     * whitespace-only), so the caller can reject the request listing every offending field.
283	     */
284	    private static void requireNonBlank(List<String> missingFields, String fieldName, String value) {
285	        if (value == null || value.isBlank()) {
286	            missingFields.add(fieldName);
287	        }
288	    }
289	
290	    /**
291	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets are stripped. When the
292	     * value carries a leading {@code '+'} its country code is kept; otherwise a {@code '+61'} country
293	     * code is assumed and a single leading {@code '0'} is dropped from the national digits. The result
294	     * must be a {@code '+'} followed by 8 to 15 digits. For example {@code "0412 345 678"} becomes
295	     * {@code "+61412345678"}.
296	     *
297	     * @param telephone the raw telephone value from the request
298	     * @return the normalized E.164 telephone number (a {@code '+'} followed by 8 to 15 digits)
299	     * @throws InvalidFieldValueException if the value cannot form a valid E.164 number
300	     */
301	    private static String normalizeTelephone(String telephone) {
302	        String e164 = toE164(telephone);
303	        if (e164 == null) {
304	            throw new InvalidFieldValueException("telephone",
305	                "Telephone must be a valid E.164 number ('+' followed by 8 to 15 digits)");
306	        }
307	        return e164;
308	    }
309	
310	    /**
311	     * Converts a raw telephone value to E.164 form, or returns {@code null} when it cannot form a
312	     * valid E.164 number. Used both to normalize incoming values and to compare against existing
313	     * owners' stored numbers when detecting duplicates.
314	     */
315	    private static String toE164(String telephone) {
316	        if (telephone == null) {
317	            return null;
318	        }
319	        String cleaned = telephone.trim().replaceAll("[\\s\\-()]", "");
320	        String digits;
321	        if (cleaned.startsWith("+")) {
322	            digits = cleaned.substring(1);
323	        } else {
324	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
325	            digits = "61" + national;
326	        }
327	        if (!digits.matches("[0-9]{8,15}")) {
328	            return null;
329	        }
330	        return "+" + digits;
331	    }
332	
333	    /**
334	     * Validates and normalizes an owner's email address. A syntactically valid address is required;
335	     * the value is returned lower-cased so it is stored and echoed back in canonical form.
336	     *
337	     * @param email the raw email value from the request (already known to be non-null)
338	     * @return the lower-cased email to be stored and returned
339	     * @throws InvalidFieldValueException if the value is not a syntactically valid email address
340	     */
341	    private static String normalizeEmail(String email) {
342	        String trimmed = email.trim();
343	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
344	            throw new InvalidFieldValueException("email", "Email must be a syntactically valid address");
345	        }
346	        return trimmed.toLowerCase(Locale.ROOT);
347	    }
348	
349	    /**
350	     * Rejects the request when {@code normalizedTelephone} is already used by any existing owner,
351	     * comparing on the E.164 form so differently-formatted stored numbers still collide.
352	     *
353	     * @param normalizedTelephone the incoming owner's normalized E.164 telephone
354	     * @throws DuplicateTelephoneException if another owner already uses this telephone
355	     */
356	    private void requireUniqueTelephone(String normalizedTelephone) {
357	        boolean taken = this.clinicService.findAllOwners().stream()
358	            .map(Owner::getTelephone)
359	            .map(OwnerRestControllerV1::toE164)
360	            .filter(existing -> existing != null)
361	            .anyMatch(normalizedTelephone::equals);
362	        if (taken) {
363	            throw new DuplicateTelephoneException(normalizedTelephone);
364	        }
365	    }
366	
367	    /**
368	     * Rejects the request when another owner already shares this household, i.e. has both the same
369	     * last name and the same address once each value is normalized (trimmed, internal whitespace
370	     * runs collapsed to a single space, and compared case-insensitively). Callers skip this check
371	     * when the request opts in via {@code sharesHousehold}.
372	     *
373	     * @param lastName the incoming owner's last name (already validated non-blank)
374	     * @param address the incoming owner's address (already validated non-blank)
375	     * @throws DuplicateHouseholdException if another owner already has this last name and address
376	     */
377	    private void requireUniqueHousehold(String lastName, String address) {
378	        String normalizedLastName = normalizeForHousehold(lastName);
379	        String normalizedAddress = householdAddressKey(address);
380	        boolean taken = this.clinicService.findAllOwners().stream()
381	            .anyMatch(existing -> normalizeForHousehold(existing.getLastName()).equals(normalizedLastName)
382	                && householdAddressKey(existing.getAddress()).equals(normalizedAddress));
383	        if (taken) {
384	            throw new DuplicateHouseholdException(lastName, address);
385	        }
386	    }
387	
388	    /**
389	     * Normalizes a value for household-duplicate comparison: trims leading and trailing whitespace,
390	     * collapses every internal run of whitespace to a single space, and lower-cases the result so
391	     * comparisons are case-insensitive.
392	     */
393	    private static String normalizeForHousehold(String value) {
394	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
395	    }
396	
397	    /**
398	     * Normalizes an owner's address to its canonical stored form: leading and trailing whitespace is
399	     * trimmed, every internal run of whitespace is collapsed to a single space, the value is
400	     * upper-cased, and common street-type abbreviations are expanded on a whole-word basis
401	     * ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}). A {@code null} or whitespace-only
402	     * value normalizes to the empty string, so the required-field check rejects an address that is
403	     * blank once normalized. For example {@code "  12  main  st "} becomes {@code "12 MAIN STREET"}.
404	     *
405	     * @param address the raw address value from the request (may be {@code null})
406	     * @return the normalized address, or the empty string when blank after normalization
407	     */
408	    private static String normalizeAddress(String address) {
409	        if (address == null) {
410	            return "";
411	        }
412	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
413	        if (collapsed.isEmpty()) {
414	            return "";
415	        }
416	        String[] tokens = collapsed.split(" ");
417	        StringBuilder sb = new StringBuilder();
418	        for (String token : tokens) {
419	            String expanded = switch (token) {
420	                case "ST" -> "STREET";
421	                case "RD" -> "ROAD";
422	                case "AVE" -> "AVENUE";
423	                default -> token;
424	            };
425	            if (sb.length() > 0) {
426	                sb.append(' ');
427	            }
428	            sb.append(expanded);
429	        }
430	        return sb.toString();
431	    }
432	
433	    /**
434	     * Derives the comparison key for an address used by household-duplicate detection and the shared
435	     * household identifier: the address is first put in its canonical normalized form and then
436	     * lower-cased and whitespace-collapsed, so every comparison and the derived id agree on the
437	     * normalized address regardless of the raw casing, spacing or abbreviations supplied.
438	     */
439	    private static String householdAddressKey(String address) {
440	        return normalizeForHousehold(normalizeAddress(address));
441	    }
442	
443	    /**
444	     * Joins the household identified by this last name and address, returning the stable shared
445	     * {@code householdId} to store on the joining owner. The identifier is derived deterministically
446	     * from the normalized last name and address, so every owner in the same household resolves to the
447	     * same value. Any existing household members that predate this feature (or were created without
448	     * opting in) are back-filled with the shared identifier so the whole household agrees.
449	     *
450	     * @param lastName the joining owner's last name (already validated non-blank)
451	     * @param address the joining owner's address (already validated non-blank)
452	     * @return the shared household identifier for this last name and address
453	     */
454	    private String joinHousehold(String lastName, String address) {
455	        String normalizedLastName = normalizeForHousehold(lastName);
456	        String normalizedAddress = householdAddressKey(address);
457	        String householdId = householdIdFor(normalizedLastName, normalizedAddress);
458	        this.clinicService.findAllOwners().stream()
459	            .filter(existing -> normalizeForHousehold(existing.getLastName()).equals(normalizedLastName)
460	                && householdAddressKey(existing.getAddress()).equals(normalizedAddress))
461	            .filter(existing -> !householdId.equals(existing.getHouseholdId()))
462	            .forEach(existing -> {
463	                existing.setHouseholdId(householdId);
464	                this.clinicService.saveOwner(existing);
465	            });
466	        return householdId;
467	    }
468	
469	    /**
470	     * Derives a stable household identifier from the already-normalized last name and address as the
471	     * upper-cased first 12 hex characters of their SHA-256 digest. Deterministic so the same household
472	     * always maps to the same identifier.
473	     */
474	    private static String householdIdFor(String normalizedLastName, String normalizedAddress) {
475	        try {
476	            byte[] digest = MessageDigest.getInstance("SHA-256")
477	                .digest((normalizedLastName + "|" + normalizedAddress).getBytes(StandardCharsets.UTF_8));
478	            StringBuilder sb = new StringBuilder();
479	            for (byte b : digest) {
480	                sb.append(String.format("%02X", b));
481	            }
482	            return sb.substring(0, 12);
483	        }
484	        catch (NoSuchAlgorithmException e) {
485	            throw new IllegalStateException("SHA-256 not available", e);
486	        }
487	    }
488	}
